 async function auth(kind:'login'|'signup'){const returnToAdmin=kind==='login'&&(adminLoginPending.current||page==='admin'||new URLSearchParams(window.location.search).get('view')==='admin');if(!email||!password){setNotice('Enter your email and password to continue.');return;}if(!/^\S+@\S+\.\S+$/.test(email)){setNotice('Enter a valid email address.');return;}if(kind==='signup'&&!fullName.trim()){setNotice('Enter your full name.');return;}const digits=signupPhone.replace(/\D/g,'');const normalizedPhone=digits.startsWith('233')?`0${digits.slice(3)}`:digits;if(kind==='signup'&&!/^0\d{9}$/.test(normalizedPhone)){setNotice('Enter a valid Ghana phone number, such as 0241234567.');return;}if(password.length<8){setNotice('Your password must have at least 8 characters.');return;} setBusy(true);setNotice(''); if(supabase){const result=kind==='signup'?await supabase.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin,data:{full_name:fullName.trim(),phone:normalizedPhone,...(signupAsAgent?{account_type:'agent'}:{})}}}):await supabase.auth.signInWithPassword({email,password}); if(result.error)setNotice(result.error.message); else {setUser(kind==='signup'&&!result.data.session?null:result.data.user);setModal(null);setNotice(kind==='signup'&&!result.data.session?'Check your email to confirm your account.':'Welcome back.');go(returnToAdmin?'admin':'dashboard');adminLoginPending.current=false;}} else {setUser({email,user_metadata:kind==='signup'?{full_name:fullName.trim(),phone:normalizedPhone}:{}});setModal(null);setNotice('Demo session started. Connect Supabase to enable secure accounts.');go('dashboard');}setBusy(false);}
 async function resendConfirmation(){if(!supabase||!email||!/\S+@\S+\.\S+/.test(email)){setNotice('Enter the account email address first.');return}setBusy(true);setNotice('');const {error}=await supabase.auth.resend({type:'signup',email:email.trim(),options:{emailRedirectTo:window.location.origin}});setBusy(false);setNotice(error?`Could not resend the confirmation email: ${error.message}`:'Verification email sent. Check your inbox and spam folder, confirm the address, then sign in.')}
 async function placeBulkWalletOrders(bundle:Bundle,recipients:string[]){
  const errors:string[]=[];
  if(!user){setNotice('Sign in to submit bulk orders with your wallet.');setModal('login');return{success:0,failed:recipients.length,errors:['Sign in to submit bulk orders.']}}
  if(!supabase||!liveSalesEnabled){const message='Live wallet purchases are currently unavailable.';setNotice(message);return{success:0,failed:recipients.length,errors:[message]}}
  if(walletBalance<bundle.price*recipients.length){const message=`Insufficient wallet balance. ${fmt(bundle.price*recipients.length)} is needed for ${recipients.length} orders.`;setNotice(message);return{success:0,failed:recipients.length,errors:[message]}}
  let success=0,failed=0;
  for(const recipient of recipients){
   try{
    const {data,error}=await supabase.functions.invoke('wallet-bundle-purchase',{body:{bundle_id:bundle.id,recipient_phone:recipient,idempotency_key:crypto.randomUUID(),agent_referral_code:agentReferralCode||null}});
    if(error||!data?.success){failed++;let detail=typeof data?.error==='string'?data.error:error?.message??'Order request was rejected.';if(error instanceof FunctionsHttpError){try{const payload=await error.context.clone().json();if(typeof payload?.error==='string')detail=payload.error}catch{}}errors.push(`${recipient}: ${detail}`);continue}
    const deliveryFailed=data.delivery_status==='failed';
    if(deliveryFailed){failed++;errors.push(`${recipient}: ${data.message??'Provider rejected delivery; the order was refunded.'}`)}else success++;
    setWalletBalance(Number(data.wallet_balance??walletBalance));
    if(data.created!==false){setOrders(current=>[{id:String(data.order_id??''),network:bundle.network,bundle:bundle.size,phone:recipient,price:Number(data.price??bundle.price),status:data.delivery_status==='delivered'?'Successful':deliveryFailed?'Failed':data.delivery_status==='processing'?'Processing':'Pending',date:new Date().toLocaleDateString(),createdAt:new Date().toISOString(),deliveryStatus:data.delivery_status,paymentStatus:'successful'},...current])}
   }catch(error){failed++;errors.push(`${recipient}: ${error instanceof Error?error.message:'Could not contact the order service.'}`)}
  }
  return{success,failed,errors}
 }
 async function placeOrder(){if(!selected)return;if(!/^0\d{9}$/.test(phone)){setNotice('Enter a valid 10 digit Ghanaian phone number.');return;}if(!liveSalesEnabled||!supabase){setNotice('Live checkout is not enabled. No order or payment was started.');return;}setBusy(true);const {data,error}=await supabase.functions.invoke('paystack-checkout',{body:{bundle_id:selected.id,recipient_phone:phone,idempotency_key:idempotencyKey,agent_referral_code:agentReferralCode||null}});setBusy(false);if(error||!data?.authorization_url){let message=data?.error??error?.message??'Could not start secure checkout. No payment was taken.';const context=error&&typeof error==='object'&&'context'in error?error.context:null;if(context instanceof Response){try{const payload=await context.clone().json();if(typeof payload?.error==='string')message=payload.error}catch{}}setNotice(message);return;}try{localStorage.setItem('cheapdatabundle-last-paystack-order',JSON.stringify({phone,reference:data.reference}))}catch{}window.location.assign(data.authorization_url);}
 async function placeWalletOrder(){if(!selected)return;if(!user){setNotice('Sign in to buy a bundle with your wallet.');setModal('login');return}if(!supabase||!liveSalesEnabled){setNotice('Live wallet purchases are currently unavailable.');return}if(!/^0\d{9}$/.test(phone)){setNotice('Enter a valid 10 digit Ghanaian phone number.');return}if(walletBalance<selected.price){setNotice('Your wallet balance is too low. Add funds or choose Paystack checkout.');return}setBusy(true);setNotice('');try{const {data,error}=await supabase.functions.invoke('wallet-bundle-purchase',{body:{bundle_id:selected.id,recipient_phone:phone,idempotency_key:walletOrderKey,agent_referral_code:agentReferralCode||null}});if(error||!data?.success){let message=data?.error??error?.message??'Could not place the wallet order.';const context=error&&typeof error==='object'&&'context'in error?error.context:null;if(context instanceof Response){try{const payload=await context.clone().json();if(typeof payload?.error==='string')message=payload.error}catch{}}setNotice(message);setBusy(false);return}setWalletBalance(Number(data.wallet_balance??walletBalance));const deliveryStatus=String(data.delivery_status??'processing');const status:Order['status']=deliveryStatus==='delivered'?'Successful':deliveryStatus==='failed'?'Failed':deliveryStatus==='processing'?'Processing':'Pending';if(data.created!==false){setOrders(current=>[{id:String(data.order_id??''),network:selected.network,bundle:selected.size,phone,price:Number(data.price??selected.price),status,date:new Date().toLocaleDateString(),createdAt:new Date().toISOString(),deliveryStatus:data.delivery_status,paymentStatus:'successful'},...current])}setModal(null);setNotice(data.message??(status==='Successful'?'Data delivered successfully.':'Wallet order submitted.'));setWalletOrderKey(crypto.randomUUID())}catch{setNotice('Could not contact the order service. Check your orders before trying again.')}finally{setBusy(false)}}
 async function startWalletDeposit(){const amount=Number(depositAmount);if(!walletDepositsEnabled){setNotice('Wallet deposits are currently unavailable.');return}if(!user||!supabase){setNotice('Sign in to add funds to your wallet.');setModal('login');return}if(!Number.isFinite(amount)||amount<1||amount>10000||Math.round(amount*100)!==amount*100){setNotice('Enter an amount from GHS 1.00 to GHS 10,000.00.');return}setBusy(true);setNotice('');try{const {data,error}=await supabase.functions.invoke('paystack-wallet-checkout',{body:{amount,idempotency_key:crypto.randomUUID()}});if(error instanceof FunctionsHttpError){console.error('Function status:',error.context.status);console.error('Function response:',await error.context.clone().text())}else if(error){console.error('Invocation error:',error)}if(error||!data?.authorization_url){let message=data?.error??error?.message??'Could not start wallet top-up. No payment was taken.';const context=error&&typeof error==='object'&&'context'in error?error.context:null;if(context instanceof Response){try{const payload=await context.clone().json();if(typeof payload?.error==='string')message=payload.error}catch{}}setNotice(message);setBusy(false);return}window.location.assign(data.authorization_url)}catch{setNotice('Could not start wallet top-up. No payment was taken.');setBusy(false)}}
