function OrderTable({orders,client,userId}:{orders:Order[];client:SupabaseClient|null;userId:string}){
 const [query,setQuery]=useState(''),[status,setStatus]=useState(''),[payment,setPayment]=useState(''),[range,setRange]=useState('all'),[applied,setApplied]=useState({query:'',status:'',payment:'',range:'all'});
 const filtered=orders.filter(order=>{const label=order.deliveryStatus==='delivered'||order.status==='Successful'?'Delivered':order.deliveryStatus==='failed'||order.status==='Failed'?'Failed':order.deliveryStatus==='processing'||order.status==='Processing'?'Processing':'Pending';const paid=order.paymentStatus==='successful'?'paid':order.paymentStatus==='failed'?'failed':'unpaid';const text=`${order.id} ${order.phone} ${order.bundle} ${order.network}`.toLowerCase();const now=new Date();const created=new Date(order.createdAt);const inRange=applied.range==='today'?created.toDateString()===now.toDateString():applied.range==='7days'?created>=new Date(Date.now()-7*86400000):applied.range==='30days'?created>=new Date(Date.now()-30*86400000):true;return(!applied.query||text.includes(applied.query.toLowerCase()))&&(!applied.status||label.toLowerCase()===applied.status.toLowerCase())&&(!applied.payment||paid===applied.payment)&&inRange});
 const apply=(event:FormEvent)=>{event.preventDefault();setApplied({query,status,payment,range})};const reset=()=>{setQuery('');setStatus('');setPayment('');setRange('all');setApplied({query:'',status:'',payment:'',range:'all'})};
 return <div className="customer-order-history"><form className="customer-order-filters" onSubmit={apply}><label>Search<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Order #, phone, plan…"/></label><label>Order status<select value={status} onChange={e=>setStatus(e.target.value)}><option value="">All statuses</option><option>Delivered</option><option>Processing</option><option>Pending</option><option>Failed</option></select></label><label>Payment status<select value={payment} onChange={e=>setPayment(e.target.value)}><option value="">All payments</option><option value="paid">Paid</option><option value="unpaid">Unpaid</option><option value="failed">Failed</option></select></label><label>Date range<select value={range} onChange={e=>setRange(e.target.value)}><option value="all">All time</option><option value="today">Today</option><option value="7days">Last 7 days</option><option value="30days">Last 30 days</option></select></label><button className="customer-order-apply" type="submit">Apply</button><button className="customer-order-reset" type="button" onClick={reset}>Reset</button></form>{filtered.length?<div className="customer-order-table-wrap"><table className="customer-order-table"><thead><tr><th>Date &amp; time</th><th>Package details</th><th>Recipient</th><th>Price paid</th><th>Status</th><th>Report</th></tr></thead><tbody>{filtered.map(o=>{const delivered=o.deliveryStatus==='delivered';const label=delivered?'Delivered':o.deliveryStatus==='failed'||o.status==='Failed'?'Failed':o.deliveryStatus==='processing'||o.status==='Processing'?'Processing':'Pending';return <tr key={o.id}><td><b>{new Date(o.createdAt).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</b><small>{new Date(o.createdAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</small></td><td><div className="customer-order-package"><NetworkLogo network={o.network} className={`order-net ${colors[o.network]}`} isIshare={o.network==='AT'&&/i[\s-]?share/i.test(`${o.bundle} ${o.subcategory??''}`)}/><span><b>{o.bundle}</b><small>{o.network}{o.subcategory?` · ${o.subcategory}`:o.network==='MTN'?' · MTN':''}</small></span></div></td><td><b>{o.phone}</b><small>Source: Dashboard</small></td><td><b>{fmt(o.price)}</b><small className={`customer-payment-tag ${o.paymentStatus==='successful'?'paid':o.paymentStatus==='failed'?'failed':''}`}>{o.paymentStatus==='successful'?'Paid':o.paymentStatus==='failed'?'Failed':'Unpaid'}</small></td><td><span className={`customer-delivery-tag ${label.toLowerCase()}`}>{label.toUpperCase()}</span></td><td><OrderComplaintAction client={client} userId={userId} orderId={o.id} delivered={delivered} order={{phone:o.phone,bundle:o.bundle,network:o.network,createdAt:o.createdAt}}/></td></tr>})}</tbody></table></div>:orders.length?<div className="empty-orders"><b>No orders match these filters.</b></div>:<div className="empty-orders"><div className="empty-icon"><Clock3/></div><b>No orders yet</b><span>Your bundle purchases will show up here.</span></div>}</div>
}


